422 :     // property collapsing can introduce new constants (e.g. enum values).
423 :     // TODO(johnlenz): make checkConsts namespace aware so it can be run
424 :     // as during the checks phase.
425 :     passes.add(checkConsts);
426 : 
427 :     // The Caja library adds properties to Object.prototype, which breaks
428 :     // most for-in loops.  This adds a check to each loop that skips
429 :     // any property matching /___$/.
430 :     if (options.ignoreCajaProperties) {
431 :       passes.add(ignoreCajaProperties);
432 :     }
433 : 
434 :     assertAllOneTimePasses(passes);
435 : 
436 :     if (options.smartNameRemoval || options.reportPath != null) {
437 :       passes.addAll(getCodeRemovingPasses());
438 :       passes.add(smartNamePass);
439 :     }
440 : 
441 :     // This needs to come after the inline constants pass, which is run within
442 :     // the code removing passes.
443 :     if (options.closurePass) {
444 :       passes.add(closureOptimizePrimitives);
445 :     }
446 : 
447 :     // TODO(user): This forces a first crack at crossModuleCodeMotion
448 :     // before devirtualization. Once certain functions are devirtualized,
449 :     // it confuses crossModuleCodeMotion ability to recognized that
450 :     // it is recursive.
451 : 
452 :     // TODO(user): This is meant for a temporary quick win.
453 :     // In the future, we might want to improve our analysis in
454 :     // CrossModuleCodeMotion so we don't need to do this.
455 :     if (options.crossModuleCodeMotion) {
456 :       passes.add(crossModuleCodeMotion);
457 :     }
458 : 
459 :     // Method devirtualization benefits from property disambiguation so
460 :     // it should run after that pass but before passes that do
461 :     // optimizations based on global names (like cross module code motion
462 :     // and inline functions).  Smart Name Removal does better if run before
463 :     // this pass.
464 :     if (options.devirtualizePrototypeMethods) {
465 :       passes.add(devirtualizePrototypeMethods);
466 :     }
467 : 
468 :     if (options.customPasses != null) {
469 :       passes.add(getCustomPasses(
470 :           CustomPassExecutionTime.BEFORE_OPTIMIZATION_LOOP));
471 :     }
472 : 
473 :     passes.add(createEmptyPass("beforeMainOptimizations"));
474 : 
475 :     passes.addAll(getMainOptimizationLoop());
476 : 
477 :     if (options.specializeInitialModule) {
478 :       // When specializing the initial module, we want our fixups to be
479 :       // as lean as possible, so we run the entire optimization loop to a
480 :       // fixed point before specializing, then specialize, and then run the
481 :       // main optimization loop again.
482 : 
483 :       if (options.crossModuleCodeMotion) {
484 :         passes.add(crossModuleCodeMotion);
485 :       }
486 : 
487 :       if (options.crossModuleMethodMotion) {
488 :         passes.add(crossModuleMethodMotion);
489 :       }
490 : 
491 :       passes.add(specializeInitialModule);
492 :       passes.addAll(getMainOptimizationLoop());
493 :     }
494 : 
495 :     passes.add(createEmptyPass("beforeModuleMotion"));
496 : 
497 :     if (options.crossModuleCodeMotion) {
498 :       passes.add(crossModuleCodeMotion);
499 :     }
500 : 
501 :     if (options.crossModuleMethodMotion) {
502 :       passes.add(crossModuleMethodMotion);
503 :     }
504 : 
505 :     passes.add(createEmptyPass("afterModuleMotion"));
506 : 
507 :     // Some optimizations belong outside the loop because running them more
508 :     // than once would either have no benefit or be incorrect.
509 :     if (options.customPasses != null) {
510 :       passes.add(getCustomPasses(
511 :           CustomPassExecutionTime.AFTER_OPTIMIZATION_LOOP));
512 :     }
513 : 
514 :     if (options.flowSensitiveInlineVariables) {
515 :       passes.add(flowSensitiveInlineVariables);
516 : 
517 :       // After inlining some of the variable uses, some variables are unused.
518 :       // Re-run remove unused vars to clean it up.
519 :       if (options.removeUnusedVars || options.removeUnusedLocalVars) {
520 :         passes.add(removeUnusedVars);
521 :       }
522 :     }
523 : 
524 :     // Running this pass again is required to have goog.events compile down to
525 :     // nothing when compiled on its own.
526 :     if (options.smartNameRemoval) {
527 :       passes.add(smartNamePass2);
528 :     }
529 : 
530 :     if (options.collapseAnonymousFunctions) {
531 :       passes.add(collapseAnonymousFunctions);
532 :     }
533 : 
534 :     // Move functions before extracting prototype member declarations.
535 :     if (options.moveFunctionDeclarations ||
536 :         // renamePrefixNamescape relies on moveFunctionDeclarations
537 :         // to preserve semantics.
538 :         options.renamePrefixNamespace != null) {
539 :       passes.add(moveFunctionDeclarations);
540 :     }
541 : 
542 :     if (options.anonymousFunctionNaming ==
543 :         AnonymousFunctionNamingPolicy.MAPPED) {
544 :       passes.add(nameMappedAnonymousFunctions);
545 :     }
546 : 
547 :     // The mapped name anonymous function pass makes use of information that
548 :     // the extract prototype member declarations pass removes so the former
549 :     // happens before the latter.
550 :     //
551 :     // Extracting prototype properties screws up the heuristic renaming
552 :     // policies, so never run it when those policies are requested.
553 :     if (options.extractPrototypeMemberDeclarations &&
554 :         (options.propertyRenaming != PropertyRenamingPolicy.HEURISTIC &&
555 :          options.propertyRenaming !=
556 :             PropertyRenamingPolicy.AGGRESSIVE_HEURISTIC)) {
557 :       passes.add(extractPrototypeMemberDeclarations);
558 :     }
559 : 
560 :     if (options.ambiguateProperties &&
561 :         (options.propertyRenaming == PropertyRenamingPolicy.ALL_UNQUOTED)) {
562 :       passes.add(ambiguateProperties);
563 :     }
564 : 
565 :     if (options.propertyRenaming != PropertyRenamingPolicy.OFF) {
566 :       passes.add(renameProperties);
567 :     }
568 : 
569 :     // Reserve global names added to the "windows" object.
570 :     if (options.reserveRawExports) {
571 :       passes.add(gatherRawExports);
572 :     }
573 : 
574 :     // This comes after property renaming because quoted property names must
575 :     // not be renamed.
576 :     if (options.convertToDottedProperties) {
577 :       passes.add(convertToDottedProperties);
578 :     }
579 : 
580 :     // Property renaming must happen before this pass runs since this
581 :     // pass may convert dotted properties into quoted properties.  It
582 :     // is beneficial to run before alias strings, alias keywords and
583 :     // variable renaming.
584 :     if (options.rewriteFunctionExpressions) {
585 :       passes.add(rewriteFunctionExpressions);
586 :     }
587 : 
588 :     // This comes after converting quoted property accesses to dotted property
589 :     // accesses in order to avoid aliasing property names.
590 :     if (!options.aliasableStrings.isEmpty() || options.aliasAllStrings) {
591 :       passes.add(aliasStrings);
592 :     }
593 : 
594 :     if (options.aliasExternals) {
595 :       passes.add(aliasExternals);
596 :     }
597 : 
598 :     if (options.aliasKeywords) {
599 :       passes.add(aliasKeywords);
600 :     }
601 : 
602 :     // Passes after this point can no longer depend on normalized AST
603 :     // assumptions.
604 :     passes.add(markUnnormalized);
605 : 
606 :     if (options.coalesceVariableNames) {
607 :       passes.add(coalesceVariableNames);
608 : 
609 :       // coalesceVariables creates identity assignments and more redundant code
610 :       // that can be removed, rerun the peephole optimizations to clean them
611 :       // up.
612 :       if (options.foldConstants) {
613 :         passes.add(peepholeOptimizations);
614 :       }
615 :     }
616 : 
617 :     if (options.collapseVariableDeclarations) {
618 :       passes.add(exploitAssign);
619 :       passes.add(collapseVariableDeclarations);
620 :     }
621 : 
622 :     // This pass works best after collapseVariableDeclarations.
623 :     passes.add(denormalize);
624 : 
625 :     if (options.instrumentationTemplate != null) {
626 :       passes.add(instrumentFunctions);
627 :     }
628 : 
629 :     if (options.variableRenaming != VariableRenamingPolicy.ALL) {
630 :       // If we're leaving some (or all) variables with their old names,
631 :       // then we need to undo any of the markers we added for distinguishing
632 :       // local variables ("$$1").
633 :       passes.add(invertContextualRenaming);
634 :     }
635 : 
636 :     if (options.variableRenaming != VariableRenamingPolicy.OFF) {
637 :       passes.add(renameVars);
638 :     }
639 : 
640 :     if (options.groupVariableDeclarations) {
641 :       passes.add(groupVariableDeclarations);
642 :     }
643 : 
644 :     // This pass should run after names stop changing.
645 :     if (options.processObjectPropertyString) {
646 :       passes.add(objectPropertyStringPostprocess);
647 :     }
648 : 
649 :     if (options.labelRenaming) {
650 :       passes.add(renameLabels);
651 :     }
652 : 
653 :     if (options.foldConstants) {
654 :       passes.add(latePeepholeOptimizations);
655 :     }
656 : 
657 :     if (options.anonymousFunctionNaming ==
658 :         AnonymousFunctionNamingPolicy.UNMAPPED) {
659 :       passes.add(nameUnmappedAnonymousFunctions);
660 :     }
661 : 
662 :     passes.add(stripSideEffectProtection);
663 : 
664 :     if (options.renamePrefixNamespace != null) {
665 :       if (!GLOBAL_SYMBOL_NAMESPACE_PATTERN.matcher(
666 :           options.renamePrefixNamespace).matches()) {
667 :         throw new IllegalArgumentException(
668 :             "Illegal character in renamePrefixNamespace name: "
669 :             + options.renamePrefixNamespace);
670 :       }
671 :       passes.add(rescopeGlobalSymbols);
672 :     }
673 : 
674 :     // Safety checks
675 :     passes.add(sanityCheckAst);
676 :     passes.add(sanityCheckVars);
677 : 
678 :     return passes;
679 :   }"

