"718 :   private List<PassFactory> getCodeRemovingPasses() {
719 :     List<PassFactory> passes = Lists.newArrayList();
720 :     if (options.collapseObjectLiterals && !isInliningForbidden()) {
721 :       passes.add(collapseObjectLiterals);
722 :     }
723 : 
724 :     if (options.inlineVariables || options.inlineLocalVariables) {
725 :       passes.add(inlineVariables);
726 :     } else if (options.inlineConstantVars) {
727 :       passes.add(inlineConstants);
728 :     }
729 : 
730 :     if (options.foldConstants) {
731 :       // These used to be one pass.
732 :       passes.add(minimizeExitPoints);
733 :       passes.add(peepholeOptimizations);
734 :     }
735 : 
736 :     if (options.removeDeadCode) {
737 :       passes.add(removeUnreachableCode);
738 :     }
739 : 
740 :     if (options.removeUnusedPrototypeProperties) {
741 :       passes.add(removeUnusedPrototypeProperties);
742 :     }
743 : 
744 :     if (options.removeUnusedClassProperties && !isInliningForbidden()) {
745 :       passes.add(removeUnusedClassProperties);
746 :     }
747 : 
748 :     assertAllLoopablePasses(passes);
749 :     return passes;
750 :   }"
